"""Complete original HTML cold-entry state machine. No browser or provider."""
import json
import shutil
import subprocess
from pathlib import Path

import pytest

HARNESS = r'''
const fs=require('fs'),vm=require('vm'),assert=require('assert'),crypto=require('crypto');
const mode=process.argv[1],id=n=>'00000000-0000-4000-8000-'+String(n).padStart(12,'0'),sha=c=>c.repeat(64);let seq=50;
class Element{
constructor(tag='div'){this.tagName=tag;this.children=[];const named={};this.elements=new Proxy([],{get:(a,k)=>k in a?a[k]:(named[k]??=new Element('input'))});this.dataset={};this.textContent='';this.value='';this.hidden=true;this.disabled=false;this.checked=false;this.style={};this.listeners={};}
append(...x){this.children.push(...x)}replaceChildren(...x){this.children=x;this.textContent=''}prepend(...x){this.children.unshift(...x)}reset(){}addEventListener(n,f){(this.listeners[n]??=[]).push(f)}setAttribute(){}removeAttribute(n){delete this[n]}closest(){return null}querySelectorAll(selector){const found=[];for(const e of this.children){if(selector==='input[data-cold-goal]'&&e.dataset?.coldGoal)found.push(e);if(e.querySelectorAll)found.push(...e.querySelectorAll(selector));}return found}scrollIntoView(){}focus(){}select(){}remove(){}get firstElementChild(){return this.children[0]}get options(){return this.children.filter(x=>x.tagName==='option')}get selectedOptions(){return this.options.filter(x=>x.value===this.value)}
}

const principal='fixture-owner-b',actor=crypto.createHash('sha256').update(JSON.stringify({actor_id:principal})).digest('hex'),park='park-b',calls=[],stages=['CREATE_RUN','CREATE_PREPARATION','SAVE_REQUEST','ADD_need_summary','ADD_material_outline'];
const clone=x=>JSON.parse(JSON.stringify(x));
const canonical=x=>Array.isArray(x)?'['+x.map(canonical).join(',')+']':x&&typeof x==='object'?'{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+canonical(x[k])).join(',')+'}':JSON.stringify(x);
const hash=x=>crypto.createHash('sha256').update(canonical(x)).digest('hex');
const flags={read_only:true,automatically_replayed:false,provider_enabled:false,execution_enabled:false,new_grants:false,automatic_adoption:false};
const row={instance_id:'park-b-current-material-instance',config_revision:1,config_sha256:sha('a'),release_id:id(1),release_revision:1,release_sha256:sha('b'),service_id:'synthetic-material-preparation',title:'本人资料服务',supported_goals:['LOCAL_MATERIAL_PREPARATION'],fields:{need_summary:'park_b_need',material_outline:'park_b_outline'}};
let denied=false,blockedDirectory=false,db=null,delayResolve=null,waitDirectory=false,lost=false,stageLost=false;
function directory(){const x={scope:'SYNTHETIC_PARK_INSTANCE_COLD_INPUT_DIRECTORY',actor_ref:actor,park_id:park,...flags,has_unknown_sources:false,instances:[clone(row)],allowed_goals:['LOCAL_MATERIAL_PREPARATION']};if(mode==='bad_directory_scope')x.scope='LIVE';if(mode==='bad_directory_flags')x.provider_enabled=true;if(mode==='bad_directory_union')x.allowed_goals=[];if(mode==='bad_directory_duplicate')x.instances.push(clone(row));if(mode==='bad_directory_fields')x.instances[0].fields.other='arbitrary';if(mode==='bad_directory_count')x.instances=Array.from({length:17},(_,n)=>({...row,instance_id:'instance-'+n}));if(mode==='bad_directory_goal')x.instances[0].supported_goals=['LIVE_GOAL'];return x;}
function command(name){if(name==='CREATE_RUN')return {schema_version:'parkweave-domain/0.1',action:'case.create',goal:db.input.goal,source:'SYNTHETIC'};if(name==='CREATE_PREPARATION')return {run_id:id(3),service_id:'synthetic-material-preparation',service_version:1,reviewer_id:'fixture-reviewer-b'};if(name==='SAVE_REQUEST')return {expected_preparation_revision:1,request_text:db.input.goal,required_goals:db.input.required_goals,planning_constraints:db.input.planning_constraints};return {action:'ADD_EVIDENCE',expected_revision:name==='ADD_need_summary'?2:3,...Object.values(db.input.fields).find(m=>m.slot===name.slice(4))};}
function admit(name){const body=command(name);db.stages.push({name,request_key:'tc_'+db.cold_input_id.replace(/-/g,'')+'_'+name,body_sha256:hash(body),body,state:'ADMITTED'});db.product_observations.push({name,request_key:'tc_'+db.cold_input_id.replace(/-/g,'')+'_'+name,status:'NOT_OBSERVED',result:null,automatically_replayed:false,not_committed_final:false});}
function dto(){const x=clone(db);if(mode==='bad_subject')x.actor_ref='other-owner';if(mode==='bad_original_key')x.request_key=id(99);if(mode==='bad_cold_flags')x.execution_enabled=true;if(mode==='bad_hash')x.stages[0].body_sha256=sha('c');if(mode==='bad_saved_goals')x.input.required_goals=['duplicate','duplicate'];if(mode==='bad_saved_material')x.input.fields.park_b_need.slot='other';if(mode==='bad_actor_mapping')x.binding.instance.roles.enterprise_operator='other-principal';if(mode==='bad_stage_action'){x.stages[0].body.action='fault.record';x.stages[0].body_sha256=hash(x.stages[0].body);}if(mode==='bad_observation_key')x.product_observations[0].request_key=id(99);if(mode==='bad_duplicate_stage')x.stages.push(clone(x.stages[0]));return x;}
async function fetchAPI(path,options={}){calls.push({path,options});const method=options.method||'GET',key=options.headers?.['Idempotency-Key'];if(denied)return {ok:false,status:403,json:async()=>({})};let body;
if(path==='/api/service-instance-configurations'){if(waitDirectory)await new Promise(resolve=>delayResolve=resolve);if(mode==='disabled'||blockedDirectory)return {ok:false,status:403,json:async()=>({})};body=directory();}
else if(path==='/api/service-instance-cold-inputs'&&method==='POST'){const input=JSON.parse(options.body);input.planning_constraints={excluded_roles:[],additional_requirements:[]};db={scope:'SYNTHETIC_PARK_INSTANCE_COLD_INPUT',actor_ref:actor,request_key:key,park_id:park,...flags,cold_input_id:id(2),binding:{kind:'PARK_INSTANCE_COLD_INPUT_V1',instance:{...row,roles:{enterprise_operator:principal,park_specialist:'fixture-reviewer-b'}}},input,current_available:true,stages:[],product_observations:[],automatic_execution:false,business_publication:false,case_goal_completed:false};admit('CREATE_RUN');if(mode==='lost_prepare'&&!lost){lost=true;throw Error('synthetic lost prepare response');}body=dto();}
else if(path==='/api/service-instance-cold-inputs/recovery'){if(!db)return {ok:false,status:403,json:async()=>({})};body=dto();}
else if(path.startsWith('/api/service-instance-cold-inputs/prepare-stage?stage=')&&method==='POST'){const name=decodeURIComponent(path.split('=')[1]);assert(stages.includes(name));if(mode==='unknown_stage_prepare'&&!stageLost){stageLost=true;throw Error('synthetic unobserved stage-description response');}admit(name);if(mode==='lost_stage_prepare'&&!stageLost){stageLost=true;throw Error('synthetic lost stage-description response');}body=dto();}
else if(method==='POST'&&(['/api/runs','/api/preparations','/api/preparations/'+id(4)+'/request-intent','/api/preparations/'+id(4)+'/commands'].includes(path))){const stage=db.stages.find(s=>s.request_key===key);assert(stage);assert.equal(canonical(JSON.parse(options.body)),canonical(stage.body));if(mode==='unknown_send'&&!lost){lost=true;throw Error('synthetic lost send before observation');}const obs=db.product_observations.find(o=>o.name===stage.name);obs.status='COMMITTED';obs.result=stage.name==='CREATE_RUN'?{run_id:id(3),run_state:'QUEUED',case_id:null}:{preparation_id:id(4),case_id:id(5),run_id:id(3),actor_id:principal,scope:'SYNTHETIC_LOCAL_PREPARATION_ONLY',revision:stages.indexOf(stage.name),action:stage.name==='CREATE_PREPARATION'?'CREATE':stage.name==='SAVE_REQUEST'?'UPDATE_REQUEST':'ADD_EVIDENCE'};body=obs.result;if(mode==='lost_send'&&!lost){lost=true;throw Error('synthetic lost committed send response');}}
else throw Error('unexpected request '+method+' '+path);
return {ok:true,status:200,json:async()=>clone(body)};}
function page(seed={}){const elements=new Map(),get=id=>{if(!elements.has(id)){const e=new Element();e.id=id;elements.set(id,e)}return elements.get(id)},store={...seed};const storage=new Proxy({getItem:n=>store[n]??null,setItem:(n,v)=>store[n]=v,removeItem:n=>delete store[n]},{ownKeys:()=>Object.keys(store),getOwnPropertyDescriptor:()=>({enumerable:true,configurable:true})});get('run-access-valid-until').parentElement={firstChild:{textContent:''}};
const ctx=vm.createContext({console,Date,JSON,Map,Set,WeakMap,Number,String,Error,encodeURIComponent,URLSearchParams,structuredClone,TextEncoder,Option:function(t,v){const x=new Element('option');x.textContent=t;x.value=v;return x},crypto:{randomUUID:()=>id(seq++),subtle:require('crypto').webcrypto.subtle},localStorage:storage,setTimeout:()=>1,clearTimeout:()=>{},location:{search:''},document:{getElementById:get,createElement:t=>new Element(t),querySelectorAll:()=>[],body:new Element('body'),addEventListener(){}},window:{addEventListener(){}},fetch:fetchAPI});
vm.runInContext(fs.readFileSync('src/parkweave/web.html','utf8').match(/<script[^>]*>([\s\S]*?)<\/script>/)[1],ctx);return {get,read:s=>vm.runInContext(s,ctx),snapshot:()=>({...store})};}

const posts=()=>calls.filter(c=>c.options.method==='POST');
function storageHandle(p){const raw=p.snapshot()['parkweave.cold-input-original-key.v1'];return raw&&JSON.parse(raw);}
async function fill(p){p.get('cold-goal').value='本次新企业诉求含中文与换行\n不复制旧材料';p.get('cold-need').value='<script>literal new need</script>';p.get('cold-outline').value='new outline';p.get('cold-reason').value='本次明确新输入';p.get('cold-extra').value=mode==='unsupported_goal'?'需要外部资格判定':'';const choices=p.get('cold-goals').querySelectorAll('input[data-cold-goal]');choices[0].checked=true;p.get('cold-prepare-confirm').checked=true;await p.get('cold-prepare').onclick();}
async function send(p){p.get('cold-send-confirm').checked=true;await p.get('cold-stage-send').onclick();}
(async()=>{let p=page();p.get('token').value='SYNTHETIC_UI_SESSION';assert.equal(calls.length,0);if(mode==='late_directory'){waitDirectory=true;const waiting=p.get('cold-directory-read').onclick();while(!delayResolve)await new Promise(r=>setImmediate(r));p.get('token').value='SYNTHETIC_OTHER';p.read('coldClear()');delayResolve();await waiting;assert.equal(p.read('coldDirectory'),null);assert.equal(posts().length,0);}
else{await p.get('cold-directory-read').onclick();if(mode==='disabled'||mode.startsWith('bad_directory')){assert.equal(p.read('coldDirectory'),null);assert.equal(posts().length,0);assert(p.get('cold-form').hidden);}
else{assert.equal(p.read('coldDirectory.instances.length'),1);if(mode==='without_confirmation'){await p.get('cold-prepare').onclick();assert.equal(posts().length,0);}
else if(mode==='other_pending'){p.read('entryWriteRequests.set("fixture",{kind:"HTTP_WRITE"})');await fill(p);assert.equal(posts().length,0);assert.equal(storageHandle(p),undefined);}
else{await fill(p);assert.equal(posts().length,1);const handle=storageHandle(p);assert.deepEqual(Object.keys(handle).sort(),['actor','key','sent','v']);assert.deepEqual(handle.sent,['PREPARE']);assert(!JSON.stringify(p.snapshot()).includes('new outline'));assert(!JSON.stringify(p.snapshot()).includes('SYNTHETIC_UI_SESSION'));assert(!JSON.stringify(p.snapshot()).includes('script'));const sentInput=JSON.parse(posts()[0].options.body);assert.deepEqual(Object.keys(sentInput.fields).sort(),['park_b_need','park_b_outline']);assert.equal(sentInput.fields.park_b_need.slot,'need_summary');assert.equal(sentInput.fields.park_b_need.text,'<script>literal new need</script>');
if(mode.startsWith('bad_')){assert.equal(p.read('coldView'),null);assert(storageHandle(p));}
else if(mode==='original_guard'){let refused=false;try{await p.read('servicePlanWrite("ADOPT")');}catch(e){refused=e.message.includes('原新事项');}assert(refused);assert.equal(posts().length,1);}
else if(mode==='unsupported_goal'){assert(sentInput.required_goals.includes('需要外部资格判定'));assert.equal(posts().length,1);}
else if(mode==='revoked_read'){const snapshot=p.snapshot();p=page(snapshot);p.get('token').value='SYNTHETIC_UI_SESSION';await p.get('cold-recover').onclick();assert.equal(posts().length,1);assert.equal(p.read('coldView.actor_ref'),actor);assert.equal(p.read('coldDirectory'),null);p.get('cold-send-confirm').checked=true;await p.get('cold-stage-send').onclick();assert.equal(posts().length,1);assert.deepEqual(p.snapshot(),snapshot);}
else if(mode==='revoked_403'){p.read('preparationView={preparation:{id:"'+id(4)+'"}};servicePlanView={private:true}');const snapshot=p.snapshot();denied=true;await p.get('cold-recover').onclick();assert.equal(p.read('coldView'),null);assert.equal(p.get('cold-need').value,'');assert.equal(p.read('preparationView'),null);assert.equal(p.read('servicePlanView'),null);assert.deepEqual(p.snapshot(),snapshot);}
else if(mode==='cold_reload'){const snapshot=p.snapshot();p=page(snapshot);p.get('token').value='SYNTHETIC_UI_SESSION';assert.equal(posts().length,1);await p.get('cold-recover').onclick();assert.equal(posts().length,1);assert.equal(p.read('coldView.request_key'),handle.key);assert.deepEqual(p.snapshot(),snapshot);}
else if(mode==='late_recovery'){const c=p.read('coldContext()');p.get('token').value='SYNTHETIC_OTHER';p.read('coldClear()');await p.read('coldRecoverAt('+JSON.stringify(c)+','+JSON.stringify(handle)+')').catch(()=>{});assert.equal(p.read('coldView'),null);assert(storageHandle(p));}
else{if(mode==='no_send_confirmation'){await p.get('cold-stage-send').onclick();assert.equal(posts().length,1);}else{await send(p);assert.equal(posts().length,2);assert.deepEqual(storageHandle(p).sent,['PREPARE','CREATE_RUN']);if(mode==='unknown_send'){assert.equal(p.read('coldView.product_observations[0].status'),'NOT_OBSERVED');const snapshot=p.snapshot();p=page(snapshot);p.get('token').value='SYNTHETIC_UI_SESSION';await p.get('cold-recover').onclick();await p.get('cold-directory-read').onclick();await send(p);assert.equal(posts().length,2);assert.deepEqual(p.snapshot(),snapshot);}else{assert.equal(p.read('coldView.product_observations[0].result.run_state'),'QUEUED');assert(p.get('cold-stage-prepare').disabled);await p.get('cold-stage-prepare').onclick();assert.equal(posts().length,2);db.product_observations[0].result.run_state='SUCCEEDED';db.product_observations[0].result.case_id=id(5);await p.get('cold-recover').onclick();for(const name of stages.slice(1)){assert.equal(p.get('cold-stage').value,name);assert(!p.get('cold-stage-prepare').disabled);const count=posts().length;await p.get('cold-stage-prepare').onclick();if(mode==='lost_stage_prepare'&&name==='CREATE_PREPARATION'){assert(p.read('coldView.stages.some(s=>s.name==="CREATE_PREPARATION")'));assert(storageHandle(p).sent.includes('PREPARE_STAGE:CREATE_PREPARATION'));await p.get('cold-stage-prepare').onclick();assert.equal(posts().length,count+1);await p.get('cold-recover').onclick();}if(mode==='unknown_stage_prepare'&&name==='CREATE_PREPARATION'){const snapshot=p.snapshot();assert(storageHandle(p).sent.includes('PREPARE_STAGE:CREATE_PREPARATION'));p=page(snapshot);p.get('token').value='SYNTHETIC_UI_SESSION';await p.get('cold-recover').onclick();await p.get('cold-directory-read').onclick();assert(p.get('cold-stage-prepare').disabled);await p.get('cold-stage-prepare').onclick();assert.equal(posts().length,count+1);assert.deepEqual(p.snapshot(),snapshot);console.log(JSON.stringify({result:'PASS',mode,posts:posts().length,completeOriginalHTML:true,simulatedDTO:true}));return;}assert.equal(posts().length,count+1);assert(p.get('cold-command').textContent.includes('Idempotency-Key'));assert(p.get('cold-command').textContent.includes(db.stages.at(-1).request_key));assert(p.get('cold-stage-send').disabled);await send(p);assert.equal(posts().length,count+2);}assert.equal(posts().length,10);assert(!p.get('cold-open').disabled);assert.equal(p.read('coldUnresolved()'),false);const count=posts().length;await send(p);assert.equal(posts().length,count);assert(db.input.fields.park_b_need.text.includes('script'));if(mode==='readonly_completed'){const snapshot=p.snapshot(),count=calls.length;p=page(snapshot);p.get('token').value='SYNTHETIC_UI_SESSION';await p.get('cold-recover').onclick();assert.equal(calls.length,count+1);assert(p.get('cold-open').disabled);const text=p.get('cold-input-history').children.map(e=>e.textContent).join('\n');assert(text.includes(db.input.goal));assert(db.input.required_goals.every(g=>text.includes(g)));assert(text.includes('<script>literal new need</script>'));assert(text.includes('new outline'));assert(text.includes('本次新输入：need_summary'));const before=calls.length;await p.get('cold-open').onclick();assert.equal(calls.length,before);assert.deepEqual(p.snapshot(),snapshot);assert.equal(p.read('coldView.actor_ref'),actor);assert(!p.get('cold-new').disabled);await p.get('cold-new').onclick();assert.equal(calls.length,before);assert.equal(storageHandle(p),undefined);assert.equal(p.read('coldView'),null);p.get('token').value='SYNTHETIC_REVIEWER_SESSION';p.read('coldClear()');assert.equal(p.read('coldUnresolved()'),false);}if(mode==='completed_open'){p.read("loadPreparation=async function(id,{role}={}){prepRole=role;};loadServiceCasePlan=async function(){};");await p.get('cold-open').onclick();assert.equal(p.read('prepRole'),'enterprise_operator');assert.equal(storageHandle(p),undefined);p.get('token').value='SYNTHETIC_REVIEWER_SESSION';p.read('coldClear()');assert.equal(p.read('coldUnresolved()'),false);assert.equal(posts().length,10);}if(mode==='completed_new'){await p.get('cold-new').onclick();assert.equal(storageHandle(p),undefined);assert.equal(p.read('coldView'),null);assert.equal(p.read('coldDirectory'),null);await p.get('cold-directory-read').onclick();await fill(p);assert.equal(posts().length,11);assert.notEqual(storageHandle(p).key,handle.key);}}}
}
}
}
}
console.log(JSON.stringify({result:'PASS',mode,posts:posts().length,completeOriginalHTML:true,simulatedDTO:true}));})().catch(e=>{console.error(e.stack);process.exitCode=1});
'''


@pytest.mark.parametrize("mode", ["happy", "unknown_stage_prepare", "lost_stage_prepare", "readonly_completed", "bad_saved_goals", "bad_saved_material", "completed_open", "completed_new", "original_guard", "other_pending", "bad_actor_mapping", "disabled", "without_confirmation", "no_send_confirmation", "lost_prepare", "lost_send", "unknown_send", "cold_reload", "revoked_read", "revoked_403", "late_directory", "late_recovery", "unsupported_goal", "bad_directory_scope", "bad_directory_flags", "bad_directory_union", "bad_directory_duplicate", "bad_directory_fields", "bad_directory_count", "bad_directory_goal", "bad_subject", "bad_original_key", "bad_cold_flags", "bad_hash", "bad_stage_action", "bad_observation_key", "bad_duplicate_stage"])
def test_cold_entry_complete_original_html(mode):
    assert shutil.which("node")
    root = Path(__file__).resolve().parents[1]
    result = subprocess.run(["node", "-e", HARNESS, mode], cwd=root, text=True, capture_output=True, timeout=25)
    assert result.returncode == 0, result.stdout + result.stderr
    evidence = json.loads(result.stdout.strip().splitlines()[-1])
    assert evidence["result"] == "PASS" and evidence["completeOriginalHTML"] is True
